#!/usr/bin/env bash
#
# START modification - generated by AI (GitHub Copilot, DeepSeek V4 Flash)
#
# device-reinstall.sh — recover from INSTALL_FAILED_UPDATE_INCOMPATIBLE.
#
# That error means the build already on the device is signed with a different
# key (e.g. the auto-generated ~/.android/debug.keystore was recreated), and
# Android refuses to replace it. The only fix is to uninstall first — which
# wipes the app data — so this script backs up the vault, reinstalls, restores
# the data, verifies it and then launches.
#
#   scripts/device-reinstall.sh [SERIAL] [TARBALL]
#
# Prevention: pin a stable keystore in build.gradle `signingConfigs.debug`
# instead of relying on the regenerated default debug keystore.
#
set -euo pipefail

APP_ID="com.u17od.upm"
ACTIVITY="${APP_ID}/.AppEntryActivity"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
APPDATA="$SCRIPT_DIR/device-appdata.sh"
TARBALL="${TARBALL:-/tmp/upm-appdata.tar}"

step() { printf '\n==> %s\n' "$*"; }
die()  { printf '[error] %s\n' "$*" >&2; exit 1; }

command -v adb >/dev/null 2>&1 || die "adb is not on PATH"
[[ -x "$APPDATA" ]] || die "missing $APPDATA"

SERIAL="${1:-}"
if [[ -z "$SERIAL" ]]; then
    found="$(adb devices | awk '$1 !~ /^emulator-/ && $2 == "device" { print $1 }')"
    count="$(printf '%s\n' "$found" | grep -c '^[^[:space:]]' || true)"
    (( count == 1 )) || die "need exactly one physical device (found $count) — pass SERIAL"
    SERIAL="$found"
fi

cd "$(dirname "$0")/.."

installed=0
adb -s "$SERIAL" shell pm path "$APP_ID" >/dev/null 2>&1 && installed=1

if (( installed )); then
    step "1/6 back up the app data (vault) on $SERIAL"
    "$APPDATA" backup "$SERIAL" "$TARBALL"
    before="$(tar xOf "$TARBALL" ./files/upm.db 2>/dev/null | md5sum | awk '{print $1}')"
else
    step "1/6 $APP_ID is not installed — nothing to back up"
    before=""
fi

step "2/6 uninstall the old (differently signed) build"
adb -s "$SERIAL" uninstall "$APP_ID" || echo "    (nothing to uninstall)"

step "3/6 install the debug build"
"$SCRIPT_DIR/install-on-device.sh" --serial "$SERIAL"

if [[ -n "$before" ]]; then
    step "4/6 restore the app data"
    "$APPDATA" restore "$SERIAL" "$TARBALL"

    step "5/6 verify the vault"
    after="$(adb -s "$SERIAL" exec-out run-as "$APP_ID" cat files/upm.db | md5sum | awk '{print $1}')"
    printf '    backup: %s\n    device: %s\n' "$before" "$after"
    [[ "$before" == "$after" ]] || die "vault mismatch after restore"
    echo "    [ok] vault restored intact"
else
    step "4/6+5/6 no vault to restore"
fi

step "6/6 launch"
adb -s "$SERIAL" shell am start -n "$ACTIVITY" >/dev/null
echo "    started $ACTIVITY"

step "Done"
# END modification - generated by AI (GitHub Copilot, DeepSeek V4 Flash)
